// The code table
// ---------------------------------------------------------------------------

/**
 * @param {{
 *   sha256: (text: string) => string,
 *   now?: () => number,
 *   caps?: Partial<typeof LAN_CAPS>,
 *   via?: 'cloud'|'lan',
 *   log?: (line: string) => void,
 *   onEnd?: (room: string, hash: string, reason: string) => void,
 *   timers?: { setInterval, clearInterval },
 * }} options
 */
